using DarouichTravaux.Application; using DarouichTravaux.Infrastructure; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<AppDbContext>(o => o.UseNpgsql(builder.Configuration.GetConnectionString("PostgreSQL")));
builder.Services.AddIdentity<ApplicationUser, IdentityRole<Guid>>(o => { o.Password.RequiredLength=10; o.Password.RequireUppercase=true; o.Password.RequireLowercase=true; o.Password.RequireDigit=true; o.Password.RequireNonAlphanumeric=true; o.Lockout.MaxFailedAccessAttempts=5; }).AddEntityFrameworkStores<AppDbContext>().AddDefaultTokenProviders();
builder.Services.ConfigureApplicationCookie(o => { o.LoginPath="/login"; o.Cookie.HttpOnly=true; o.Cookie.SecurePolicy=CookieSecurePolicy.Always; o.Cookie.SameSite=SameSiteMode.Strict; o.ExpireTimeSpan=TimeSpan.FromMinutes(30); o.SlidingExpiration=true; });
builder.Services.AddAuthorization(o => o.FallbackPolicy = o.DefaultPolicy); builder.Services.AddScoped<IClientService,ClientService>(); builder.Services.AddScoped<IProjectService,ProjectService>(); builder.Services.AddScoped<IInvoiceService,InvoiceService>(); builder.Services.AddScoped<IDashboardService,DashboardService>(); builder.Services.AddRazorPages(o => o.Conventions.ConfigureFilter(new Microsoft.AspNetCore.Mvc.AutoValidateAntiforgeryTokenAttribute()));
var app=builder.Build(); if (!app.Environment.IsDevelopment()) app.UseExceptionHandler("/Error"); app.UseHsts(); app.UseHttpsRedirection(); app.UseStaticFiles(); app.UseRouting(); app.UseAuthentication(); app.UseAuthorization(); app.MapRazorPages(); app.Run();
